#pragma once
#include <Arduino.h>

// Single-page touch joystick. It sends /drive?x=&y= every 100 ms as a heartbeat
// and never queues more than one request, so a slow link cannot pile up stale commands.
static const char INDEX_HTML[] PROGMEM = R"HTML(<!DOCTYPE html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no">
<title>Rover</title>
<style>
body{margin:0;background:#111;color:#eee;font-family:sans-serif;text-align:center;touch-action:none;user-select:none}
#pad{width:300px;height:300px;border-radius:50%;background:#222;border:2px solid #444;margin:20px auto;position:relative}
#knob{width:90px;height:90px;border-radius:50%;background:#2a7;position:absolute;left:105px;top:105px}
#st{font-size:20px;margin-top:12px}
button{font-size:22px;padding:12px 40px;background:#a22;color:#fff;border:0;border-radius:8px}
</style></head><body>
<div id="st">connecting...</div>
<div id="pad"><div id="knob"></div></div>
<button id="stop">STOP</button>
<script>
const pad=document.getElementById('pad'),knob=document.getElementById('knob'),st=document.getElementById('st');
let x=0,y=0,busy=false,active=false;
function setKnob(){knob.style.left=(105+x*105)+'px';knob.style.top=(105-y*105)+'px';}
function move(e){if(!active)return;const r=pad.getBoundingClientRect();
 let dx=(e.clientX-r.left-r.width/2)/(r.width/2),dy=-(e.clientY-r.top-r.height/2)/(r.height/2);
 const m=Math.hypot(dx,dy);if(m>1){dx/=m;dy/=m;}x=dx;y=dy;setKnob();e.preventDefault();}
function release(){active=false;x=0;y=0;setKnob();}
pad.addEventListener('pointerdown',e=>{active=true;pad.setPointerCapture(e.pointerId);move(e);});
pad.addEventListener('pointermove',move);
pad.addEventListener('pointerup',release);
pad.addEventListener('pointercancel',release);
document.getElementById('stop').onclick=()=>{release();fetch('/stop');};
document.addEventListener('visibilitychange',()=>{if(document.hidden)release();});
function tick(){if(busy)return;busy=true;
 const c=new AbortController();const t=setTimeout(()=>c.abort(),400);
 fetch('/drive?x='+Math.round(x*100)+'&y='+Math.round(y*100),{signal:c.signal})
 .then(r=>r.json()).then(j=>{st.textContent=j.v.toFixed(2)+' V  '+j.s;})
 .catch(()=>{st.textContent='link lost';})
 .finally(()=>{clearTimeout(t);busy=false;});}
setInterval(tick,100);
</script></body></html>)HTML";

#include <Arduino.h>
#include <WiFi.h>
#include <WebServer.h>
#include "pins.h"
#include "webpage.h"

// ---------------- Tunables ----------------
static const char*    AP_PASS          = "rover1234";   // WPA2 needs >= 8 chars
static const uint32_t PWM_FREQ_HZ      = 20000;         // above hearing range
static const uint8_t  PWM_BITS         = 10;
static const uint32_t PWM_FULL         = (1u << PWM_BITS); // LEDC: 2^bits = constant high
static const float    DUTY_CAP         = 0.75f;         // 8.4 V * 0.75 = 6.3 V on 6 V motors
static const float    DEADBAND         = 0.06f;
static const float    TURN_GAIN        = 0.6f;          // softer steering for a small wheelbase
static const float    RAMP_PER_S       = 4.0f;          // 0 -> full in 250 ms, limits start surge
static const uint32_t CMD_TIMEOUT_MS   = 500;           // failsafe
static const bool     INVERT_LEFT      = false;
static const bool     INVERT_RIGHT     = true;          // motors face opposite ways on the deck

static const float    DIV_RATIO        = 33.0f / 133.0f; // R1 100k over 33k
static const float    VBAT_PRESENT_V   = 3.0f;   // below this we are on USB only
static const float    VBAT_LOW_V       = 6.8f;   // warn (3.4 V/cell)
static const float    VBAT_LOW_CLEAR_V = 7.0f;
static const float    VBAT_CUT_V       = 6.4f;   // stop driving (3.2 V/cell)
static const float    VBAT_CUT_CLEAR_V = 7.2f;   // only a recharged pack re-enables
static const uint32_t VBAT_CUT_HOLD_MS = 3000;   // ignore brief sag on motor starts
static const uint32_t VBAT_PERIOD_MS   = 50;
static const float    VBAT_EMA_ALPHA   = 0.1f;

// ---------------- State ----------------
enum BattState { BATT_NONE, BATT_OK, BATT_LOW, BATT_CUT };

WebServer server(80);

static float     targetL = 0, targetR = 0;
static float     outL = 0, outR = 0;
static uint32_t  lastCmdMs = 0;
static bool      haveCmd = false;
static bool      driverAwake = false;

static float     vbat = 0;
static bool      vbatSeeded = false;
static BattState batt = BATT_NONE;
static uint32_t  belowCutSince = 0;
static uint32_t  lastVbatMs = 0;
static uint32_t  lastMotorUs = 0;

// ---------------- Motor driver ----------------
// Slow-decay (drive/brake) PWM: one input held high, the other PWM'd inverted.
// This gives a more linear speed response at low duty than fast decay.
static void writeBridge(uint8_t ch1, uint8_t ch2, float cmd) {
  float d = fabsf(cmd) * DUTY_CAP;
  if (d > DUTY_CAP) d = DUTY_CAP;
  uint32_t low = (uint32_t)((1.0f - d) * PWM_FULL);
  if (!driverAwake) {
    ledcWrite(ch1, 0);
    ledcWrite(ch2, 0);
  } else if (cmd > 0.0f) {
    ledcWrite(ch1, PWM_FULL);
    ledcWrite(ch2, low);
  } else if (cmd < 0.0f) {
    ledcWrite(ch1, low);
    ledcWrite(ch2, PWM_FULL);
  } else {
    ledcWrite(ch1, PWM_FULL);  // both high = brake, holds the rover on stop
    ledcWrite(ch2, PWM_FULL);
  }
}

static void setDriverAwake(bool awake) {
  if (awake == driverAwake) return;
  driverAwake = awake;
  digitalWrite(PIN_DRV_NSLEEP, awake ? HIGH : LOW);
  if (awake) delayMicroseconds(1000);  // DRV8833 wake time before outputs are valid
}

static void applyMotors() {
  writeBridge(CH_AIN1, CH_AIN2, INVERT_LEFT ? -outL : outL);
  writeBridge(CH_BIN1, CH_BIN2, INVERT_RIGHT ? -outR : outR);
}

static void stopNow() {
  targetL = targetR = 0;
  outL = outR = 0;
  applyMotors();
}

static float slew(float cur, float tgt, float step) {
  // Speed up gently, but slow down or reverse-to-zero instantly for safety.
  if (fabsf(tgt) < fabsf(cur) || (tgt * cur) < 0.0f) {
    if ((tgt * cur) < 0.0f) return 0.0f;
    return tgt;
  }
  if (tgt > cur) return min(tgt, cur + step);
  return max(tgt, cur - step);
}

static bool driveAllowed() {
  return batt == BATT_OK || batt == BATT_LOW;
}

static void updateMotors() {
  uint32_t nowUs = micros();
  uint32_t dtUs = nowUs - lastMotorUs;
  if (dtUs < 10000) return;  // 100 Hz
  lastMotorUs = nowUs;

  bool linkOk = haveCmd && (millis() - lastCmdMs) < CMD_TIMEOUT_MS;
  if (!linkOk || !driveAllowed()) {
    stopNow();
    setDriverAwake(false);
    return;
  }

  float step = RAMP_PER_S * (dtUs / 1e6f);
  outL = slew(outL, targetL, step);
  outR = slew(outR, targetR, step);
  setDriverAwake(true);
  applyMotors();
}

// ---------------- Battery ----------------
static void updateBattery() {
  uint32_t now = millis();
  if (now - lastVbatMs < VBAT_PERIOD_MS) return;
  lastVbatMs = now;

  float v = analogReadMilliVolts(PIN_VBAT_SENSE) / 1000.0f / DIV_RATIO;
  if (!vbatSeeded) { vbat = v; vbatSeeded = true; }
  else vbat += VBAT_EMA_ALPHA * (v - vbat);

  if (vbat < VBAT_PRESENT_V) {
    batt = BATT_NONE;  // USB bench power, no VM: keep the bridge asleep
    belowCutSince = 0;
    return;
  }
  if (batt == BATT_NONE) batt = BATT_OK;

  if (batt == BATT_CUT) {
    if (vbat > VBAT_CUT_CLEAR_V) batt = BATT_OK;
    return;
  }

  if (vbat < VBAT_CUT_V) {
    if (belowCutSince == 0) belowCutSince = now ? now : 1;
    if (now - belowCutSince >= VBAT_CUT_HOLD_MS) {
      batt = BATT_CUT;
      Serial.printf("VBAT %.2f V: cut-off, motors disabled\n", vbat);
      return;
    }
  } else {
    belowCutSince = 0;
  }

  if (batt == BATT_OK && vbat < VBAT_LOW_V) batt = BATT_LOW;
  else if (batt == BATT_LOW && vbat > VBAT_LOW_CLEAR_V) batt = BATT_OK;
}

static const char* battText() {
  switch (batt) {
    case BATT_NONE: return "no battery (USB)";
    case BATT_OK:   return "ok";
    case BATT_LOW:  return "LOW battery";
    case BATT_CUT:  return "BATTERY CUT-OFF";
  }
  return "?";
}

// ---------------- Status LED ----------------
static void setLed(bool g, bool r) {
  digitalWrite(PIN_LED_GREEN, g ? HIGH : LOW);
  digitalWrite(PIN_LED_RED, r ? HIGH : LOW);
}

static void updateLed() {
  uint32_t t = millis();
  bool linkOk = haveCmd && (t - lastCmdMs) < CMD_TIMEOUT_MS;
  switch (batt) {
    case BATT_CUT:  setLed(false, (t / 250) % 2); break;            // fast red blink
    case BATT_NONE: { bool p = (t / 500) % 2; setLed(p, !p); } break; // alternate = USB bench
    case BATT_LOW:  setLed(false, true); break;                     // solid red
    case BATT_OK:   setLed(linkOk ? true : ((t / 500) % 2), false); break; // green solid / blink
  }
}

// ---------------- Web ----------------
static void sendStatus() {
  char buf[80];
  snprintf(buf, sizeof(buf), "{\"v\":%.2f,\"s\":\"%s\"}", vbat, battText());
  server.sendHeader("Cache-Control", "no-store");
  server.send(200, "application/json", buf);
}

static void handleRoot() {
  server.send_P(200, "text/html", INDEX_HTML);
}

static void handleDrive() {
  float x = constrain(server.arg("x").toInt(), -100, 100) / 100.0f;
  float y = constrain(server.arg("y").toInt(), -100, 100) / 100.0f;
  if (fabsf(x) < DEADBAND) x = 0;
  if (fabsf(y) < DEADBAND) y = 0;

  // Arcade mix, then normalise so turning at full speed keeps the ratio.
  float l = y + x * TURN_GAIN;
  float r = y - x * TURN_GAIN;
  float m = max(fabsf(l), fabsf(r));
  if (m > 1.0f) { l /= m; r /= m; }

  targetL = l;
  targetR = r;
  lastCmdMs = millis();
  haveCmd = true;
  sendStatus();
}

static void handleStop() {
  stopNow();
  lastCmdMs = millis();
  haveCmd = true;
  sendStatus();
}

// ---------------- Setup / loop ----------------
void setup() {
  // Outputs off before anything else so the bridge cannot twitch at boot.
  pinMode(PIN_DRV_NSLEEP, OUTPUT);
  digitalWrite(PIN_DRV_NSLEEP, LOW);
  const uint8_t inPins[4] = {PIN_AIN1, PIN_AIN2, PIN_BIN1, PIN_BIN2};
  const uint8_t chans[4]  = {CH_AIN1, CH_AIN2, CH_BIN1, CH_BIN2};
  for (int i = 0; i < 4; i++) {
    pinMode(inPins[i], OUTPUT);
    digitalWrite(inPins[i], LOW);
    ledcSetup(chans[i], PWM_FREQ_HZ, PWM_BITS);
    ledcWrite(chans[i], 0);
    ledcAttachPin(inPins[i], chans[i]);
  }
  pinMode(PIN_LED_GREEN, OUTPUT);
  pinMode(PIN_LED_RED, OUTPUT);
  setLed(false, false);

  Serial.begin(115200);

  analogReadResolution(12);
  analogSetPinAttenuation(PIN_VBAT_SENSE, ADC_11db);  // tap is 1.6-2.1 V

  uint8_t mac[6];
  WiFi.macAddress(mac);
  char ssid[20];
  snprintf(ssid, sizeof(ssid), "Rover-%02X%02X", mac[4], mac[5]);
  WiFi.mode(WIFI_AP);
  WiFi.softAP(ssid, AP_PASS, 6, 0, 2);
  WiFi.setTxPower(WIFI_POWER_11dBm);  // desk range only; less RF current on the buck
  WiFi.setSleep(false);                 // lower command latency

  server.on("/", handleRoot);
  server.on("/drive", handleDrive);
  server.on("/stop", handleStop);
  server.onNotFound([]() { server.send(404, "text/plain", "not found"); });
  server.begin();

  lastMotorUs = micros();
  Serial.printf("Rover up. SSID %s pass %s -> http://%s/\n", ssid, AP_PASS,
                WiFi.softAPIP().toString().c_str());
}

void loop() {
  server.handleClient();
  updateBattery();
  updateMotors();
  updateLed();

  static uint32_t lastLog = 0;
  if (millis() - lastLog > 2000) {
    lastLog = millis();
    Serial.printf("VBAT %.2f V [%s] L %.2f R %.2f sta %d\n", vbat, battText(), outL, outR,
                  WiFi.softAPgetStationNum());
  }
  delay(1);  // yield to the Wi-Fi stack
}
